"""Real map/list/popups, area, municipality selection and Q16 confirmations."""
from qa_support import *
q=QA('map_ui');q.result['maps']=[]
def click(selector):q.ev('document.querySelector('+json.dumps(selector)+').click();true',userGesture=True)
def open_map(n='58',option='Sim'):
 q.question(n);q.ev('document.querySelector("#w27DetailAlternative").value='+json.dumps(option)+';document.querySelector("#w27OpenMap").click();true');q.wait('!!W27SchoolMap.state?.model')
def close_map():click('#w27Close');q.wait("document.querySelector('#questionDialog').open");q.close_dialog()
def work():
 q.c.call('Emulation.setDeviceMetricsOverride',{'width':1366,'height':1000,'deviceScaleFactor':1,'mobile':False});q.go();q.check(q.ev("performance.getEntriesByType('resource').filter(r=>r.name.includes('/api/school-map/')).length") ==0,'Cover does not request any nominal map partition');q.check(q.ev('W25OperationalModel.cachedUFs')==0,'Cover still loads zero W25 nominal UF partitions')
 for uf,ibge,n in [('PA','1506807','58'),('PI','2211001','58'),('AM','1301605','28')]:
  q.select({'uf':uf,'ibge':ibge});before=q.ev('W15.summary()');open_map(n,'Sim'if n=='58'else'__all_valid__');m=q.ev('W27SchoolMap.state.model');q.check(m['selectedSchools']==m['mappedSchools']+m['unmappedSchools'],'Real '+ibge+' selection reconciles mapped and not mapped');q.check(q.ev('W27SchoolMap.state.clusters.reduce((s,c)=>s+c.rows.length,0)')==m['mappedSchools'],'Real '+ibge+' all unique cluster items reconcile');q.check(q.ev('W15.summary()')==before,'School map leaves original W25 coverage unchanged');q.ev("document.querySelector('#w27Svg').scrollIntoView({block:'center',behavior:'instant'});true");q.screenshot('map-'+ibge+'.png');q.result['maps'].append({'ibge':ibge,'question':n,'selected':m['selectedSchools'],'mapped':m['mappedSchools'],'unmapped':m['unmappedSchools']})
  click('#w27ZoomIn');q.check(q.ev('W27SchoolMap.state.model.selectedSchools')==m['selectedSchools'],'Zoom does not change source denominator');rect=q.ev("(()=>{const r=document.querySelector('#w27Svg').getBoundingClientRect();return{x:r.left+20,y:r.top+25}})()");q.c.call('Input.dispatchMouseEvent',{'type':'mousePressed','x':rect['x'],'y':rect['y'],'button':'left','clickCount':1});q.c.call('Input.dispatchMouseEvent',{'type':'mouseMoved','x':rect['x']+45,'y':rect['y']+25,'button':'left','buttons':1});q.c.call('Input.dispatchMouseEvent',{'type':'mouseReleased','x':rect['x']+45,'y':rect['y']+25,'button':'left','clickCount':1});q.check(q.ev('Math.hypot(...W27SchoolMap.state.pan)>0'),'Actual pointer pan changes only the camera');q.ev('W27SchoolMap.state.pan=[0,0];document.querySelector("#w27ZoomOut").click();true');time.sleep(.3);q.ev("document.querySelector('#w27Svg [data-cluster]').dispatchEvent(new MouseEvent('click',{bubbles:true}));true");q.check(q.ev("!document.querySelector('#w27Popup').hidden&&document.querySelector('#w27Popup').innerText.includes('INEP')"),'Popup exposes actual permitted identity and current response');q.screenshot('popup-'+ibge+'.png');click('#w27PopupClose');click('#w27ListTab');q.check(q.ev("document.querySelectorAll('#w27List tbody tr').length")==min(20,m['selectedSchools']),'List paginates the same selected schools');first=m['rows'][0]['inep'];q.ev('document.querySelector("#w27Search").value='+json.dumps(first)+';document.querySelector("#w27Search").dispatchEvent(new Event("input",{bubbles:true}));true');q.check(q.ev("document.querySelectorAll('#w27List tbody tr').length===1&&document.querySelector('#w27SearchCount').innerText.includes('Busca aplicada ao mapa e à lista')"),'Search restricts both views with explicit label');q.check(q.ev('W27SchoolMap.state.model.selectedSchools')==m['selectedSchools'],'Search retains original selection denominator');close_map()
 # Real all-missing coordinates context, never a fake center point.
 q.select({'uf':'BA','ibge':'2903508'});open_map('19','__all_valid__');q.check(q.ev("W27SchoolMap.state.model.selectedSchools>0&&W27SchoolMap.state.model.mappedSchools===0&&document.querySelectorAll('#w27Svg [data-cluster]').length===0"),'Real municipality without usable coordinates retains its authorized list and has no invented markers');click('#w27ListTab');q.check(q.ev("document.querySelectorAll('#w27List tbody tr').length>0"),'Authorized nonlocalized schools remain in list');close_map()
 # Choose a municipality explicitly from a broader context.
 q.select({'uf':'PI'});q.question('58');click('#w27OpenMap');q.wait("!!document.querySelector('#w27Municipality')");q.ev("document.querySelector('#w27Municipality').value='2211001';document.querySelector('#w27ChooseMunicipality').click();true");q.wait('!!W27SchoolMap.state?.model');q.check(q.ev("W15.context.ibge==='2211001'&&W27SchoolMap.state.model.context.ibge==='2211001'"),'Municipality selector explicitly synchronizes geographic context before fetch');close_map()
 # Every Q16 choice blocks before payload; decline and confirm are distinct actions.
 q.select({'uf':'PA','ibge':'1506807','scope':'rural'});
 for g in ['indigenous','riverside','quilombola','none','other']:
  q.ev('W26Data.set('+json.dumps(g)+');true');q.wait('W15App.renderedAnalyticalContext===W15.query(W26Data.ctx())');q.question('58');before=q.ev("performance.getEntriesByType('resource').filter(r=>r.name.includes('/api/school-map/')).length");click('#w27OpenMap');q.wait("!!document.querySelector('#w27ConfirmCommunity')");q.check(q.ev("performance.getEntriesByType('resource').filter(r=>r.name.includes('/api/school-map/')).length")==before,g+' blocks nominal partition before any request');q.check(q.ev('!W27SchoolMap.state.model'),g+' cannot render or print previous nominal model');click('#w27KeepCommunity');q.wait("document.querySelector('#questionDialog').open");q.check(q.ev('W26Data.characteristic')==g,g+' cancellation preserves characterization');q.close_dialog()
 geo=q.ev('({...W15.context})');q.question('58');click('#w27OpenMap');click('#w27ConfirmCommunity');q.wait('!!W27SchoolMap.state?.model');q.check(q.ev("W26Data.characteristic==='all'&&W27SchoolMap.state.model.context.schoolCharacteristic==='all'"),'Explicit confirmation removes only Q16 before authorized map');q.check(q.ev('({...W15.context})')==geo,'Q16 removal preserves geographic and area selection');q.check(q.ev("W27SchoolMap.state.model.context.scope==='rural'"),'Confirmed map retains rural question context');close_map()
 for n in ['103','104','106']:
  q.question(n);q.check(q.ev("!document.querySelector('#w27OpenMap')&&document.querySelector('#w27DetailActions').innerText.includes('restrição nominal')"),'Q'+n+' restriction preserved in detail');q.close_dialog()
 # Context change cannot leave an old municipality map open.
 open_map();q.ev("W15.set({uf:'PI',ibge:'2211001'});true");q.wait("!document.querySelector('#w27SchoolMap').open");q.check(q.ev('W27SchoolMap.state===null'),'Geographic changes invalidate and close incompatible map');q.check(not[e for e in q.c.events if e.get('method')=='Runtime.exceptionThrown'],'Map UI and Q16 workflow have no uncaught exception')
if __name__=='__main__':sys.exit(0 if main_guard(q,work)else 1)
